import{_ as t,C as e,c as s,o as c,ak as h,G as a}from"./chunks/framework.D7ejh1zC.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"read/CSS 技术揭秘与实战通关/filter中比阴影更强大的drop-shadow阴影技巧.md","filePath":"read/css/CSS 技术揭秘与实战通关/filter中比阴影更强大的drop-shadow阴影技巧.md","lastUpdated":1786439091000}'),l={name:"read/CSS 技术揭秘与实战通关/filter中比阴影更强大的drop-shadow阴影技巧.md"};function i(p,o,n,_,w,b){const d=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return c(),s("div",null,[o[0]||(o[0]=h('<h2 id="filter中比阴影更强大的drop-shadow阴影技巧" tabindex="-1">filter中比阴影更强大的drop-shadow阴影技巧 <a class="header-anchor" href="#filter中比阴影更强大的drop-shadow阴影技巧" aria-label="Permalink to &quot;filter中比阴影更强大的drop-shadow阴影技巧&quot;">​</a></h2><p>根据 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/filter-function/drop-shadow" target="_blank" rel="noreferrer">MDN - drop-shadow</a> 文档，<code>drop-shadow()</code>：投影实际上是输入图像的 alpha 蒙版的一个模糊的、偏移的版本，用特定的颜色绘制并合成在图像下面。</p><h3 id="drop-shadow-与-box-shadow-的异同" tabindex="-1">drop-shadow 与 box-shadow 的异同 <a class="header-anchor" href="#drop-shadow-与-box-shadow-的异同" aria-label="Permalink to &quot;drop-shadow 与 box-shadow 的异同&quot;">​</a></h3><p>来看 <code>box-shadow</code> 和 <code>drop-shadow</code> 的不同之处。</p><h4 id="作用范围的差异" tabindex="-1">作用范围的差异 <a class="header-anchor" href="#作用范围的差异" aria-label="Permalink to &quot;作用范围的差异&quot;">​</a></h4><p><code>drop-shadow()</code>这个函数有点类似于 <code>box-shadow</code> 属性，但是其最本质的区别在于阴影的作用范围：</p><ol><li><code>box-shadow</code> 属性在元素的整个框后面创建一个矩形阴影</li><li><code>drop-shadow()</code> 滤镜用于创建一个符合元素（图像）本身形状（alpha 通道）的阴影</li></ol><p><img src="https://pic1.imgdb.cn/item/692698be3203f7be0033d83c.png" alt="效果比较" loading="lazy"></p><p><code>box-shadow</code> 和 <code>drop-shadow</code> 的效果对比，可以看到 <code>box-shadow</code> 的阴影是矩形，而 <code>drop-shadow</code> 的阴影是符合元素形状的。</p><h4 id="语法层面的差异-扩散半径与内阴影" tabindex="-1">语法层面的差异：扩散半径与内阴影 <a class="header-anchor" href="#语法层面的差异-扩散半径与内阴影" aria-label="Permalink to &quot;语法层面的差异：扩散半径与内阴影&quot;">​</a></h4><p>2 种阴影大同小异，需要注意的就是：</p><ul><li><code>box-shadow</code> 有内阴影，内阴影使用关键字 <code>inset</code> 进行描述，而 <code>drop-shadow</code> 是没有内阴影的；</li><li><code>box-shadow</code> 多一个阴影扩散半径参数，<code>drop-shadow</code> 是没有阴影扩散半径参数的。</li></ul><h4 id="都支持多重阴影" tabindex="-1">都支持多重阴影 <a class="header-anchor" href="#都支持多重阴影" aria-label="Permalink to &quot;都支持多重阴影&quot;">​</a></h4><p><code>box-shadow</code> 和 <code>drop-shadow</code> 都支持多重阴影。这在滤镜的章节中已提过。</p>',14)),a(d),a(r)])}const u=t(l,[["render",i]]);export{m as __pageData,u as default};
